    let masked = "";
    let last = 0;
    tokens.forEach((t, n) => {
        masked += text.slice(last, t.start) + markFor(n);
        last = t.end;
    });
    masked += text.slice(last);
    if (masked.replace(MARK_RE, "").includes(MARK_OPEN))
        return null;
    const out = rewrite(masked);
    const seen = [...out.matchAll(MARK_RE)].map((m) => markIndex(m[1]));
